function robotArt(r,large=false){const isOff=r.state==='offline',ink=isOff?'#b4c0b5':'#7a9890',fill=isOff?'#e4e9e3':'#d6e5df',accent=r.state==='alarm'?'#d4ac7f':'#4e9981';return `<svg class="robot-art ${large?'large':''}" viewBox="0 0 150 135" fill="none" aria-label="Ilustrasi robot ${r.id}"><ellipse cx="72" cy="119" rx="53" ry="9" fill="${isOff?'#edf0ec':'#eef3ef'}"/><path d="M29 116h50l-5-15H35z" fill="${fill}" stroke="${ink}" stroke-width="1.6"/><path d="M39 101V83h28v18" fill="${fill}" stroke="${ink}" stroke-width="1.8"/><path d="M44 84 31 49l18-7 18 35z" fill="${fill}" stroke="${ink}" stroke-width="2"/><path d="m39 40 47-20 10 20-46 21z" fill="${fill}" stroke="${ink}" stroke-width="2"/><path d="m91 24 31 25-8 10-31-22z" fill="${fill}" stroke="${ink}" stroke-width="2"/><path d="m122 51 11 8-7 10-12-10z" fill="${fill}" stroke="${ink}" stroke-width="1.6"/><path d="m129 64 2 14 9 5 M124 67l-3 14 7 6" stroke="${ink}" stroke-width="2"/><circle cx="49" cy="80" r="13" fill="${fill}" stroke="${ink}" stroke-width="2"/><circle cx="49" cy="80" r="7" fill="white" stroke="${ink}" stroke-width="1.5"/><circle cx="40" cy="46" r="12" fill="${fill}" stroke="${ink}" stroke-width="2"/><circle cx="40" cy="46" r="6" fill="white" stroke="${ink}" stroke-width="1.3"/><circle cx="88" cy="31" r="10" fill="${fill}" stroke="${ink}" stroke-width="2"/><circle cx="88" cy="31" r="5" fill="white" stroke="${ink}" stroke-width="1.3"/><path d="m58 43 16-7" stroke="${accent}" stroke-width="5" stroke-linecap="round"/><path d="M37 108h32 M46 90h12" stroke="${ink}" stroke-width="1.5"/><path d="m51 62 4 12" stroke="${accent}" stroke-width="3" stroke-linecap="round"/><circle cx="121" cy="56" r="3" fill="${accent}"/></svg>`;}
function stat(label,value,sub,icon,tag='',cls=''){return `<div class="stat ${cls}"><div class="stat-label">${label}${I(icon)}</div><div class="stat-value number">${value}</div><div class="stat-foot">${tag?`<em>${tag}</em>`:''}${sub}</div></div>`;}
function heading(title,subtitle,eyebrow='WELDING LINE 01',extra=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="flex gap">${extra||`${B('12 Okt 2026','date','calendar')}${B('Mode presentasi','tour-start','play','primary')}`}</div></div>`;}
function layout(){const active=state.page==='detail'?'robots':state.page;return `<aside class="sidebar ${state.mobile?'open':''}" aria-label="Navigasi utama"><a class="brand" href="#overview" aria-label="RMS overview"><span class="brandmark">${I('robot')}</span><div><div class="brand-name">RMS<span style="color:#89b89b">.</span></div><small>ROBOT MANAGEMENT</small></div></a><div class="workspace"><div class="workspace-icon">${I('layers')}</div><div><strong>Welding line 01</strong><p>ADM · Karawang</p></div><span style="margin-left:auto;color:#6b927b">${I('down')}</span></div><div class="sidebar-scroll"><div class="nav-group"><div class="nav-label">WORKSPACE</div>${navs.slice(0,6).map(([key,icon,title])=>`<button class="nav-item ${active===key?'active':''}" data-page="${key}" ${active===key?'aria-current="page"':''}>${I(icon)}${title}${key==='alarms'?'<span class="nav-count">2</span>':''}</button>`).join('')}</div><div class="nav-group"><div class="nav-label">SYSTEM</div>${navs.slice(6).map(([key,icon,title])=>`<button class="nav-item ${active===key?'active':''}" data-page="${key}" ${active===key?'aria-current="page"':''}>${I(icon)}${title}${key==='hardware'?'<span class="nav-tag">R&D</span>':''}</button>`).join('')}</div></div><div class="sidebar-bottom"><div class="collector"><div class="flex" style="font-size:11px"><span class="dot" style="color:#92ca9c"></span>SLURBT Collector<span class="badge" style="margin-left:auto;background:#aed39a12;color:#9cc68d">DEMO</span></div><p>YMConnect C++ · PostgreSQL</p></div><div class="sidebar-foot">RMS PROTOTYPE <span style="float:right">v1.0</span></div></div></aside><div class="shell"><header class="topbar"><div class="flex gap"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Buka menu">${I('menu')}</button><div class="breadcrumb">Workspace <span style="margin:0 12px">/</span> <strong>Welding line 01</strong></div></div><div class="top-actions"><button class="search-trigger" data-action="search" aria-label="Cari robot atau fitur">${I('search')}<span>Cari robot atau fitur...</span><kbd>/</kbd></button><span class="demo-pill"><span class="dot"></span>DATA SIMULASI</span><button class="icon-btn" data-page="alarms" aria-label="Lihat 2 alert aktif">${I('bell')}<span class="alert-dot"></span></button><span class="avatar" title="Presenter demo">AM</span></div></header><main id="main" class="main" tabindex="-1">${page()}<footer class="page-footer"><span>RMS · Yaskawa Robot Monitoring <span style="margin:0 7px;color:#bdc8b5">|</span> Prototype interaktif</span><span>Data simulasi · Tidak terhubung ke controller <span style="margin-left:10px">© 2026</span></span></footer></main></div>`;}
function render(scroll=false){$('#app').innerHTML=layout();document.body.classList.toggle('presentation',state.tour>=0);renderTour();if(scroll)window.scrollTo({top:0,behavior:'instant'});}
function page(){switch(state.page){case 'overview':return overview();case 'robots':return robotMonitor();case 'detail':return detail();case 'alarms':return alarmPage();case 'maintenance':return maintenance();case 'analytics':return analytics();case 'notifications':return notifications();case 'pipeline':return pipeline();case 'hardware':return hardware();case 'features':return features();default:return overview();}}
function robotCard(r){return `<button class="robot-card ${r.state}" data-robot="${r.id}" aria-label="Buka detail ${r.name}, ${states[r.state]}"><div class="between"><div><div class="robot-title">${r.name}</div><div class="robot-caption">${r.station}</div></div>${badge(r.state)}</div><div class="robot-center">${robotArt(r)}<div class="robot-readout"><div class="small">CONTROLLER</div><strong>${r.state==='offline'?'Tidak ada data':'YRC1000 · AUTO'}</strong><div class="small">${r.state==='offline'?'TERAKHIR TERLIHAT':'EXECUTING JOB'}</div><strong>${r.state==='offline'?'08:23:00':r.job}</strong></div></div><div class="robot-bottom"><div class="between"><span>Utilization <strong>${fmt(util(r),1)}%</strong></span><span>${fmt(r.hours)} h</span></div><div class="progress"><span style="width:${util(r)}%;background:${colors[r.state]}"></span></div></div></button>`;}
function robotFilter(){return `<div class="filters">${['all','running','idle','alarm','offline'].map(v=>`<button class="chip ${state.filter===v?'active':''}" data-filter="${v}">${v==='all'?'Semua':states[v]} <small>${v==='all'?8:robots.filter(r=>r.state===v).length}</small></button>`).join('')}</div>`;}
function robotSection(){const list=robots.filter(r=>state.filter==='all'||r.state===state.filter);return `<section><div class="section-heading"><h2>Robot overview <span class="count">08</span></h2><div class="flex gap">${robotFilter()}<div class="segmented"><button class="${state.layout==='grid'?'active':''}" data-layout="grid" aria-label="Tampilan grid">${I('grid')}</button><button class="${state.layout==='list'?'active':''}" data-layout="list" aria-label="Tampilan daftar">${I('list')}</button></div></div></div><div class="robot-${state.layout}">${list.map(robotCard).join('')}</div></section>`;}
function timeline(){return `<div class="timeline">${robots.map(r=>`<div class="timeline-row"><span>${r.id}</span><div class="timeline-track" aria-label="${r.id}: running ${r.run}, idle ${r.idle}, stop ${r.stop}, unknown ${r.unknown} menit">${[['run',colors.running],['idle',colors.idle],['stop',colors.alarm],['unknown',colors.offline]].map(([k,c])=>r[k]?`<span style="width:${r[k]/150*100}%;background:${c}" title="${k}: ${r[k]} menit"></span>`:'').join('')}</div><span style="text-align:right">${fmt(util(r),1)}%</span></div>`).join('')}</div><div class="timeline-axis"><span>0%</span><span>25%</span><span>50%</span><span>75%</span><span>100%</span></div>`;}
function legend(){return `<div class="legend">${[['Running',colors.running],['Idle',colors.idle],['Stop',colors.alarm],['Unknown',colors.offline]].map(([l,c])=>`<span><i style="background:${c}"></i>${l}</span>`).join('')}</div>`;}
function overview(){const s=sums(),nextPM=saved.tasks.filter(t=>t.status!=='completed').sort((a,b)=>taskProgress(a).remaining-taskProgress(b).remaining)[0];return `${heading('Line overview','Satu pandangan untuk seluruh robot di welding line.','OPERATIONS / LIVE MONITORING')}<div class="notice">${I('activity')}<span><strong>7 dari 8 controller terhubung</strong> <span style="opacity:.7;margin:0 8px">·</span> R08 membutuhkan perhatian koneksi</span><span class="right flex gap"><span id="live-time" class="mono">08:30:${String(state.tick%60).padStart(2,'0')}</span><button class="icon-btn" data-action="live" aria-label="${state.live?'Jeda':'Lanjutkan'} animasi data demo">${I(state.live?'pause':'play')}</button></span></div><div class="stats">${stat('Total robot','8 <small>/ 8 unit</small>','controller terhubung','robot','7 online')}${stat('Sedang running','5 <small>robot</small>','1 idle · 1 alarm · 1 offline','activity','62,5%')}${stat('Utilization shift',fmt(s.run/1200*100,1)+'<small>%</small>','06:00–08:30 · snapshot','chart','1.001 min run')}${stat('Alert aktif','2 <small>perlu ditinjau</small>','1 controller · 1 koneksi','bell','Perhatian','warn')}</div>${robotSection()}<div class="two-col overview-lower"><section class="panel"><div class="panel-header"><div><h2>Komposisi waktu operasi</h2><p>Shift 1 · 12 Oktober 2026, 06:00–08:30</p></div>${B('Lihat analitik','nav-analytics','arrow','text')}</div>${timeline()}<div class="timeline-foot">${legend()}<span>150 min / robot</span></div></section><section class="panel"><div class="panel-header"><div><h2>Perlu perhatian</h2><p>Prioritas monitoring & maintenance</p></div>${I('info')}</div><div class="event"><div class="event-icon">${I('warning')}</div><div class="event-content"><strong>R03 · Beban sumbu L tinggi</strong><p>Alarm ilustratif · belum berakhir</p><button class="btn text small" data-action="alarm-detail" data-id="A001">Tinjau alarm ${I('arrow')}</button></div><time>08:12</time></div><div class="event"><div class="event-icon blue">${I('link')}</div><div class="event-content"><strong>R08 · Koneksi terputus</strong><p>Data terakhir 08:23 · status belum diketahui</p><button class="btn text small" data-robot="R08">Lihat controller ${I('arrow')}</button></div><time>08:23</time></div><div class="event"><div class="event-icon green">${I('calendar')}</div><div class="event-content"><strong>${nextPM?nextPM.robot+' · PM terdekat':'Seluruh PM sudah dicatat'}</strong><p>${nextPM?fmt(taskProgress(nextPM).remaining)+' operating hours menuju interval contoh':'Buka jurnal untuk meninjau hasil pekerjaan'}</p><button class="btn text small" data-page="maintenance">Buka maintenance ${I('arrow')}</button></div><time>${nextPM?dateLabel(nextPM.date).replace(' 2026',''):'Selesai'}</time></div></section></div>`;}
function robotMonitor(){return `${heading('Robot monitor','Pilih robot untuk melihat telemetry, job, I/O, dan operating hours.','MONITORING / 8 CONTROLLERS')}<div class="status-bar mb"><span>${I('link')} <strong>7 online</strong> / 8 controller</span><span><span class="dot" style="color:var(--green)"></span>5 running</span><span><span class="dot" style="color:var(--blue)"></span>1 idle</span><span><span class="dot" style="color:var(--orange)"></span>1 alarm</span><span><span class="dot" style="color:#aaa"></span>1 offline</span><span style="margin-left:auto">Snapshot simulasi · 08:30</span></div>${robotSection()}<div class="notice blue mt">${I('info')}Seluruh nama station, alamat IP, job, dan nilai telemetry merupakan contoh untuk presentasi.</div>`;}
const axisNames=['S','L','U','R','B','T'];
const axisColors=['#528f78','#6b8eb4','#b29962','#91a766','#9b82a5','#71a5ab'];
function torqueAt(r,i,t){return [21.4,38.7,28.3,12.6,16.8,9.1][i]+robots.indexOf(r)*.6+Math.sin((t+i)/3)*1.5+Math.cos((t-i)/6)*2+(r.id==='R03'&&i===1?41:0);}
function torqueValues(r){if(r.state==='offline')return Array(6).fill(null);return axisNames.map((_,i)=>Math.round(torqueAt(r,i,state.tick)*10)/10);}
function chart(r){let lines=axisNames.map((_,a)=>{const pts=Array.from({length:46},(_,x)=>{const val=torqueAt(r,a,state.tick-(45-x));return `${48+x*10.8},${192-val*1.8}`;}).join(' ');return `<polyline points="${pts}" stroke="${axisColors[a]}" stroke-width="1.7" fill="none"/>`;}).join('');return `<svg class="chart" viewBox="0 0 570 228" role="img" aria-label="Grafik simulasi torque enam sumbu, dalam persen"><g font-size="9" fill="#9cac97">${[0,25,50,75,100].map((v,i)=>`<path d="M46 ${192-i*45}H546" stroke="#eef2eb"/><text x="9" y="${196-i*45}">${v}%</text>`).join('')}<text x="45" y="216">08:29:00</text><text x="263" y="216">08:29:30</text><text x="507" y="216">08:30:00</text></g>${r.state==='offline'?'':lines}</svg><div class="chart-key">${axisNames.map((v,i)=>`<span style="--c:${axisColors[i]}">${v} axis</span>`).join('')}</div>`;}
function detail(){const r=robots.find(x=>x.id===state.robot)||robots[0],off=r.state==='offline';return `${B('Semua robot','nav-robots','back','text back')}${heading(`${r.name} <span style="color:#b0bcb0;font-weight:400">/</span> ${r.station}`,`Yaskawa SP210 · YRC1000 · ${r.ip} (alamat contoh)`,'ROBOT DETAIL',`<select class="input" id="robot-select" aria-label="Pilih robot">${robots.map(x=>`<option value="${x.id}" ${x.id===r.id?'selected':''}>${x.id} · ${x.station}</option>`).join('')}</select>${B(state.live?'Jeda simulasi':'Lanjut simulasi','live',state.live?'pause':'play')}`)}${off?`<div class="notice warn mb">${I('warning')}Koneksi terputus pada snapshot. Nilai live ditampilkan “—”; kondisi fisik robot belum diketahui.</div>`:''}<section class="panel detail-top"><div class="robot-stage">${badge(r.state)}${robotArt(r,true)}</div><div><div class="between mb"><h2>Controller snapshot</h2><span class="live-mark">${off?'Last seen 08:23:00':state.live?'Simulasi berjalan':'Simulasi dijeda'}</span></div><div class="detail-facts">${[['Mode',off?'—':'AUTO'],['Servo',off?'—':r.state==='alarm'?'OFF':'ON'],['Cycle',off?'—':r.state==='running'?'START':r.state==='idle'?'HOLD':'STOP'],['Remote',off?'—':'REMOTE'],['Operating hours',`${fmt(r.hours)} h`],['Current job',off?'—':r.job]].map(([l,v])=>`<div class="fact"><label>${l}</label><strong>${v}</strong></div>`).join('')}</div></div></section><div class="tabbar" role="tablist" aria-label="Data robot">${[['telemetry','Torque & position'],['job','Job & I/O'],['hours','Operating hours'],['events','Alarm & history']].map(([key,label])=>`<button role="tab" aria-selected="${state.tab===key}" data-tab="${key}" class="${state.tab===key?'active':''}">${label}</button>`).join('')}</div>${state.tab==='telemetry'?telemetry(r):state.tab==='job'?jobIO(r):state.tab==='hours'?operating(r):robotEvents(r)}`;}
function telemetry(r){const values=torqueValues(r),off=r.state==='offline';return `<div class="two-col"><section class="panel"><div class="panel-header"><div><h2>Motor torque · SLURBT</h2><p>Enam sumbu robot · ilustrasi 60 detik</p></div><span class="badge tested">Sudah diuji*</span></div><div id="torque-plot">${chart(r)}</div><div class="chart-note">Grafik menggunakan sampel sintetis. Persentase dan tren hanya ilustrasi telemetry.</div></section><section class="panel"><div class="panel-header"><div><h2>Current position</h2><p>Data PULSE · per sumbu</p></div><span class="badge tested">Sudah diuji*</span></div><table class="axis-table"><thead><tr><th>Axis</th><th>Position (pulse)</th><th>Torque (%)</th></tr></thead><tbody>${axisNames.map((a,i)=>`<tr><td><span class="axis-dot" style="background:${axisColors[i]}"></span>${a}</td><td class="mono" data-pulse="${i}">${off?'—':fmt([125468,-46821,78402,1230,-18433,6431][i]+robots.indexOf(r)*523)}</td><td class="mono" data-torque="${i}">${off?'—':fmt(values[i],1)}</td></tr>`).join('')}</tbody></table></section></div><div class="notice blue mt">${I('info')}*Status “sudah diuji” mengikuti acuan project. Tampilan ini tetap simulasi. PULSE belum dikonversi menjadi koordinat Cartesian.</div>`;}
function jobIO(r){const off=r.state==='offline';const signals=['Cycle request','Part present','Jig ready','Weld ready','Cycle complete','Robot busy','Alarm active','Home position'];return `<div class="equal-col"><section class="panel"><div class="panel-header"><div><h2>Executing job</h2><p>Posisi eksekusi pada job aktif</p></div><span class="badge sdk">SDK mendukung*</span></div><div class="kv-row"><span>Job name</span><strong class="mono">${off?'—':r.job}</strong></div><div class="kv-row"><span>Line / step</span><strong>${off?'—':'42 / 118'}</strong></div><div class="kv-row"><span>Execution</span>${badge(r.state,off?'UNKNOWN':r.state==='running'?'RUNNING':'PAUSED')}</div><div class="code-box mt">Contoh urutan aktivitas, bukan listing job asli:<br>40 · Pemeriksaan kesiapan proses<br>41 · Posisi awal siklus<span class="current">42 · ${off?'Data tidak tersedia':'Proses welding — step aktif'}</span>43 · Transisi ke titik berikutnya<br>44 · Konfirmasi siklus</div></section><section class="panel"><div class="panel-header"><div><h2>I/O monitor</h2><p>Read-only · pemetaan sinyal contoh</p></div><span class="badge sdk">SDK mendukung*</span></div><div class="io-grid">${signals.map((s,i)=>{const on=!off&&([1,2].includes(i)||(r.state==='running'&&[0,3,5].includes(i))||(r.state==='idle'&&[4,7].includes(i))||(r.state==='alarm'&&i===6));return `<div class="io-bit ${on?'on':''}"><div class="between"><strong class="mono">${i<4?'IN':'OUT'} ${String(i%4+1).padStart(2,'0')}</strong><span class="io-led"></span></div><p>${s}</p><p>${off?'UNKNOWN':on?'ON · 1':'OFF · 0'}</p></div>`;}).join('')}</div><div class="notice mt">${I('shield')}Monitoring I/O bersifat baca saja.</div></section></div><div class="chart-note">*Status dukungan mengikuti gambar acuan. Mapping alamat I/O dan job perlu disesuaikan dengan controller di lapangan.</div>`;}
function operating(r){const off=r.state==='offline';return `<div class="stats">${stat('Control power ON',fmt(r.hours)+' <small>h</small>',off?'Nilai terakhir tersimpan':'Akumulasi counter contoh','clock')}${stat('Servo power ON',fmt(Math.round(r.hours*.81))+' <small>h</small>','Counter ilustratif','bolt')}${stat('Playback / running',fmt(Math.round(r.hours*.67))+' <small>h</small>','Counter ilustratif','play')}${stat('Operating time hari ini',fmt(r.run)+' <small>min</small>','Snapshot 06:00–08:30','activity')}</div><div class="equal-col"><section class="panel"><div class="panel-header"><h2>Counter sebagai dasar maintenance</h2><span class="badge sdk">SDK mendukung*</span></div><p class="small muted" style="line-height:1.9">Counter jam operasi digunakan sebagai dasar interval PM. Selisih counter sejak maintenance terakhir dibandingkan dengan interval yang ditetapkan tim maintenance.</p><div class="code-box mt">Jam sejak PM = counter saat ini − counter saat PM terakhir<br>Sisa interval = interval PM − jam sejak PM</div>${B('Lihat jadwal PM','nav-maintenance','arrow','soft mt')}</section><section class="panel"><div class="panel-header"><h2>Komposisi shift ${r.id}</h2></div>${[['Running',r.run,colors.running],['Idle',r.idle,colors.idle],['Stop',r.stop,colors.alarm],['Unknown',r.unknown,colors.offline]].map(([s,v,c])=>`<div class="kv-row"><span><i class="dot" style="background:${c}"></i>${s}</span><strong>${v} menit</strong></div>`).join('')}<div class="chart-note">Durasi kategori berjumlah 150 menit. Unknown disimpan terpisah ketika data hilang.</div></section></div>`;}
function robotEvents(r){const rows=alarms().filter(a=>a.robot===r.id);return `<section class="panel"><div class="panel-header"><div><h2>Event ${r.id}</h2><p>Alarm controller dan peristiwa koneksi dibedakan berdasarkan sumber</p></div>${B('Alarm center','nav-alarms','arrow','text')}</div>${rows.length?alarmTable(rows):`<div class="empty">${I('checkCircle')}<p>Tidak ada event untuk ${r.id} pada snapshot demo.</p></div>`}</section>`;}
function severity(a){return badge(a.severity==='critical'?'alarm':a.severity==='warning'?'investigate':'sdk',a.severity.toUpperCase());}
function filteredAlarms(){return alarms().filter(a=>(state.alarmTab==='history'||a.active)&&(state.alarmRobot==='all'||a.robot===state.alarmRobot)&&(state.alarmSeverity==='all'||a.severity===state.alarmSeverity)&&`${a.robot} ${a.code} ${a.title} ${a.kind}`.toLowerCase().includes(state.alarmSearch.toLowerCase()));}
function alarmTable(rows){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Waktu</th><th>Robot</th><th>Event / sumber</th><th>Severity</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(a=>`<tr><td class="mono">${a.time}<span class="secondary">12 Okt 2026</span></td><td><button class="action-link" data-robot="${a.robot}">${a.robot}</button></td><td>${a.title}<span class="secondary">${a.code} · ${a.kind}</span></td><td>${severity(a)}</td><td>${a.active?badge(saved.acked.includes(a.id)?'sdk':'alarm',saved.acked.includes(a.id)?'DITINJAU · AKTIF':'BELUM DITINJAU'):badge('running','BERAKHIR')}</td><td>${B('Detail','alarm-detail','chevron','small',`data-id="${a.id}"`)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Tidak ada event sesuai filter.</td></tr>'}</tbody></table></div>`;}
function alarmPage(){const rows=filteredAlarms();return `${heading('Alarm center','Tinjau alarm controller, gangguan komunikasi, dan riwayat penanganan.','OPERATIONS / ALERT MANAGEMENT',B('Ekspor CSV','export-alarms','download'))}<div class="stats">${stat('Alert aktif','2','Pada snapshot demo','bell')}${stat('Alarm controller','1','R03 · beban sumbu L','warning','','warn')}${stat('Gangguan koneksi','1','R08 · data tidak tersedia','link')}${stat('Sudah ditinjau',String(saved.acked.length),'Penandaan di dashboard','checkCircle')}</div><div class="section-heading"><div class="segmented"><button data-alarm-tab="active" class="${state.alarmTab==='active'?'active':''}">Aktif · 2</button><button data-alarm-tab="history" class="${state.alarmTab==='history'?'active':''}">Semua riwayat · 4</button></div><span class="context-label">Kode SIM = contoh skenario</span></div><div class="toolbar"><input class="input search" id="alarm-search" type="search" value="${esc(state.alarmSearch)}" placeholder="Cari alarm, kode, atau robot..." aria-label="Cari alarm"><select class="input" id="alarm-robot" aria-label="Filter robot"><option value="all">Semua robot</option>${robots.map(r=>`<option value="${r.id}" ${state.alarmRobot===r.id?'selected':''}>${r.id} · ${r.name}</option>`).join('')}</select><select class="input" id="alarm-severity" aria-label="Filter severity">${[['all','Semua severity'],['critical','Critical'],['warning','Warning'],['info','Info']].map(([v,l])=>`<option value="${v}" ${state.alarmSeverity===v?'selected':''}>${l}</option>`).join('')}</select>${B('Reset filter','reset-alarm-filter','refresh')}</div><section class="panel no-padding"><div id="alarm-results">${alarmTable(rows)}</div><div class="table-footer" id="alarm-result-count">Menampilkan ${rows.length} event · seluruh data adalah simulasi</div></section><div class="notice blue mt">${I('info')}“Tandai ditinjau” hanya mencatat review pada dashboard. Alarm tetap aktif hingga sumber event melaporkan kondisi berakhir.</div>`;}
function taskProgress(t){const r=robots.find(r=>r.id===t.robot);const elapsed=Math.max(0,r.hours-t.base);return {r,elapsed,remaining:t.interval-elapsed,percent:Math.min(100,elapsed/t.interval*100)};}
const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'});
function taskCard(t){const {r,elapsed,remaining,percent}=taskProgress(t),due=remaining<=50;return `<article class="pm-card ${due?'due':''}"><div class="between"><span class="badge ${due?'investigate':'running'}">${due?'SEGERA JATUH TEMPO':'TERJADWAL'}</span><span class="mono muted">${r.id}</span></div><h3>${esc(t.title)}</h3><p>${r.name} · ${r.station}</p><div class="pm-progress-title">${fmt(Math.max(remaining,0))}<small> h tersisa</small></div><div class="progress"><span style="width:${percent}%;background:${due?'#cda467':'#86ae83'}"></span></div><div class="pm-meta"><span>${fmt(elapsed)} / ${fmt(t.interval)} h sejak PM</span><span>${fmt(percent,1)}%</span></div><div class="kv-row mt"><span>${I('calendar')} Jadwal</span><strong>${dateLabel(t.date)}</strong></div><div class="kv-row"><span>${I('wrench')} PIC</span><strong>${esc(t.pic)}</strong></div><div class="pm-actions">${B('Detail','task-detail','file','small',`data-id="${esc(t.id)}"`)}${B('Catat pekerjaan','complete-task','check','small soft',`data-id="${esc(t.id)}"`)}</div></article>`;}
function maintenance(){const pending=saved.tasks.filter(t=>t.status!=='completed'),due=pending.filter(t=>taskProgress(t).remaining<=50).length;return `${heading('Preventive maintenance','Jaga keandalan robot melalui interval jam, jadwal, dan jurnal pekerjaan.','MAINTENANCE / PLAN & RECORD',B('Jadwalkan PM','new-task','plus','primary'))}<div class="stats">${stat('PM terjadwal',String(pending.length),'Pekerjaan dalam rencana','calendar')}${stat('Mendekati interval',String(due),'Sisa interval ≤ 50 jam','clock',due?'Perlu prioritas':'Terkendali',due?'warn':'')}${stat('Jurnal pekerjaan',String(saved.journal.length),'Riwayat yang tercatat','file')}${stat('Robot tercakup',new Set(pending.map(t=>t.robot)).size+' <small>/ 8 robot</small>','Dalam rencana demo','robot')}</div><div class="tabbar" role="tablist" aria-label="Maintenance"><button data-pm-tab="tasks" role="tab" aria-selected="${state.pmTab==='tasks'}" class="${state.pmTab==='tasks'?'active':''}">Rencana PM</button><button data-pm-tab="calendar" role="tab" aria-selected="${state.pmTab==='calendar'}" class="${state.pmTab==='calendar'?'active':''}">Kalender</button><button data-pm-tab="journal" role="tab" aria-selected="${state.pmTab==='journal'}" class="${state.pmTab==='journal'?'active':''}">Jurnal pekerjaan</button></div>${state.pmTab==='tasks'?`<div class="three-col">${pending.map(taskCard).join('')||'<div class="panel empty">Semua pekerjaan telah dicatat. Tambahkan jadwal PM berikutnya.</div>'}</div><div class="notice blue mt">${I('info')}Interval 500–1.000 jam adalah contoh. Dasar counter dan interval production mengikuti manual, konfigurasi robot, serta ketentuan maintenance internal.</div>`:state.pmTab==='calendar'?calendar():journal()}`;}
function calendar(){const start=new Date(state.year,state.month,1),blank=(start.getDay()+6)%7,total=new Date(state.year,state.month+1,0).getDate(),monthName=start.toLocaleDateString('id-ID',{month:'long',year:'numeric'});let cells=Array.from({length:blank},()=>'<div class="calendar-day blank"></div>');for(let d=1;d<=total;d++){const key=`${state.year}-${String(state.month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;const tasks=saved.tasks.filter(t=>t.date===key&&t.status!=='completed');cells.push(`<div class="calendar-day ${key==='2026-10-12'?'today':''}"><span class="day-number">${d}</span>${tasks.map(t=>`<button class="cal-event ${taskProgress(t).remaining<=50?'due':''}" data-action="task-detail" data-id="${esc(t.id)}" title="${esc(t.title)}">${t.robot} · ${esc(t.title)}</button>`).join('')}</div>`);}while(cells.length%7)cells.push('<div class="calendar-day blank"></div>');return `<section class="panel"><div class="panel-header"><div><h2>${monthName}</h2><p>Klik pekerjaan untuk melihat detail jadwal</p></div><div class="flex gap">${B('','month-prev','back','small','aria-label="Bulan sebelumnya"')}${B('Oktober 2026','month-now','','small')}${B('','month-next','arrow','small','aria-label="Bulan berikutnya"')}</div></div><p class="calendar-mobile-note">Geser kalender ke samping untuk melihat semua hari.</p><div class="calendar-scroll"><div class="calendar">${['Sen','Sel','Rab','Kam','Jum','Sab','Min'].map(d=>`<div class="day-label">${d}</div>`).join('')}${cells.join('')}</div></div><div class="chart-note">Tanggal acuan presentasi: 12 Oktober 2026. Jadwal yang ditambahkan tersimpan pada browser ini.</div></section>`;}
function journal(){return `<section class="panel"><div class="panel-header"><div><h2>Jurnal maintenance</h2><p>Catatan pekerjaan, counter jam, hasil, dan penanggung jawab</p></div>${B('Ekspor jurnal','export-journal','download','small')}</div>${[...saved.journal].sort((a,b)=>b.date.localeCompare(a.date)).map(j=>`<article class="journal-item"><div class="journal-date"><strong>${new Date(j.date+'T12:00:00').getDate()}</strong>${new Date(j.date+'T12:00:00').toLocaleDateString('id-ID',{month:'short'}).toUpperCase()}</div><div style="flex:1"><div class="between"><h3>${j.robot} · ${esc(j.title)}</h3><span class="mono muted">${fmt(j.hours)} h</span></div><p>${esc(j.notes)}</p><p>${esc(j.pic)} · ${dateLabel(j.date)}</p>${badge(j.result==='Perlu tindak lanjut'?'investigate':'running',esc(j.result))}</div></article>`).join('')}</section>`;}
function analyticsData(){const shift=sums();if(state.period==='day')return {label:'Hari demo sebelumnya · 11 Okt 2026',total:3840,run:3236,idle:330,stop:244,unknown:30,minutes:480,perRobot:[407,414,366,428,387,419,412,403]};if(state.period==='week')return {label:'Minggu demo · 5–11 Okt 2026',total:19200,run:16561,idle:1586,stop:920,unknown:133,minutes:2400,perRobot:[2120,2136,1928,2160,2041,2098,2122,1956]};return {label:'Shift 1 · 12 Okt 2026, 06:00–08:30',total:1200,...shift,minutes:150,perRobot:robots.map(r=>r.run)};}
function analytics(){const d=analyticsData(),u=d.run/d.total*100;return `${heading('Downtime & utilization','Ubah riwayat status menjadi gambaran pemanfaatan waktu robot.','ANALYTICS / OPERATING PERFORMANCE',`<select class="input" id="analytics-period" aria-label="Periode analitik"><option value="shift" ${state.period==='shift'?'selected':''}>Shift berjalan · snapshot</option><option value="day" ${state.period==='day'?'selected':''}>Hari demo sebelumnya</option><option value="week" ${state.period==='week'?'selected':''}>Minggu demo</option></select>${B('Ekspor CSV','export-analytics','download')}`)}<div class="notice">${I('calendar')}${d.label}<span class="right">${fmt(d.total)} robot-menit terjadwal · data simulasi</span></div><div class="stats">${stat('Utilization',fmt(u,1)+'<small>%</small>','Running / waktu terjadwal','chart')}${stat('Running time',fmt(d.run)+' <small>min</small>','Akumulasi 8 robot','play')}${stat('Stop / downtime',fmt(d.stop)+' <small>min</small>','Kategori stop pada demo','clock','','warn')}${stat('Data unknown',fmt(d.unknown)+' <small>min</small>','Tidak dihitung sebagai running','link')}</div><div class="two-col"><section class="panel"><div class="panel-header"><div><h2>Utilization per robot</h2><p>Persentase running terhadap waktu terjadwal per robot</p></div>${badge('running','SIMULASI')}</div>${robots.map((r,i)=>`<div class="metric-bar-row"><span>${r.id}</span><div class="progress"><span style="width:${d.perRobot[i]/d.minutes*100}%;background:${r.id==='R03'?'#c4a078':'#88ae8b'}"></span></div><strong>${fmt(d.perRobot[i]/d.minutes*100,1)}%</strong></div>`).join('')}<div class="chart-note">Setiap robot mempunyai denominator ${fmt(d.minutes)} menit pada periode ini.</div></section><section class="panel"><div class="panel-header"><h2>Distribusi waktu</h2>${I('clock')}</div><div class="percent-ring" style="--angle:${u*3.6}deg"><div><strong>${fmt(u,1)}<small style="font-size:17px">%</small></strong><small>UTILIZATION</small></div></div>${[['Running',d.run,colors.running],['Idle',d.idle,colors.idle],['Stop',d.stop,colors.alarm],['Unknown',d.unknown,colors.offline]].map(([l,v,c])=>`<div class="legend-row"><span><i class="dot" style="background:${c}"></i>${l}</span><strong>${fmt(v)} min <span class="muted" style="font-weight:400">(${fmt(v/d.total*100,1)}%)</span></strong></div>`).join('')}</section></div><div class="equal-col mt"><section class="panel"><div class="panel-header"><h2>Definisi perhitungan demo</h2>${I('info')}</div><div class="code-box">Utilization = running ÷ waktu terjadwal × 100%<br>${fmt(d.run)} ÷ ${fmt(d.total)} × 100% = ${fmt(u,1)}%</div><p class="chart-note">Unknown tetap di denominator dan dilaporkan terpisah. Planned downtime, alasan stop, dan kalender shift perlu dipetakan sebelum dipakai untuk laporan operasional. Nilai ini bukan OEE.</p></section><section class="panel"><div class="panel-header"><h2>Fokus evaluasi</h2></div><div class="event"><div class="event-icon">${I('activity')}</div><div class="event-content"><strong>R03 memiliki porsi stop lebih tinggi</strong><p>Gunakan alarm history untuk menelusuri kejadian.</p></div></div><div class="event"><div class="event-icon blue">${I('link')}</div><div class="event-content"><strong>Pisahkan koneksi hilang dari robot berhenti</strong><p>R08 offline berarti data tidak diketahui.</p></div></div>${B('Tinjau alarm terkait','nav-alarms','arrow','text mt')}</section></div>`;}
function notifications(){return `${heading('Notification center','Atur pemicu notifikasi dan pratinjau pesan untuk tim maintenance.','COMMUNICATION / EMAIL NOTIFICATION',B('Simulasikan email','test-email','mail','primary'))}<div class="notice blue mb">${I('info')}Mode demo: tidak ada email yang dikirim. Aturan, penerima, dan log uji disimpan hanya di browser ini.</div><div class="equal-col"><section class="panel"><div class="panel-header"><div><h2>Aturan notifikasi</h2><p>Aktifkan event yang perlu mendapatkan perhatian</p></div>${I('bell')}</div>${[['alarm','Alarm controller aktif','Contoh: alarm baru terdeteksi pada R03.'],['offline','Controller offline','Contoh ambang demo: data tidak masuk > 30 detik.'],['pm','Pengingat preventive maintenance','Contoh ambang demo: sisa interval ≤ 50 jam.'],['digest','Ringkasan shift','Ikhtisar utilization dan alarm setelah shift selesai.']].map(([k,l,d])=>`<div class="rule-row"><div><h3 style="font-size:12px">${l}</h3><p>${d}</p></div><button class="toggle ${saved.rules[k]?'on':''}" role="switch" aria-checked="${!!saved.rules[k]}" aria-label="${l}" data-rule="${k}"></button></div>`).join('')}<div class="mt"><label class="field" for="recipient" style="margin-bottom:6px">Penerima demo</label><div class="flex gap"><input type="email" id="recipient" class="input" value="${esc(saved.recipient)}" placeholder="maintenance@example.com" style="flex:1;min-width:0">${B('Simpan','save-recipient','','small')}</div><p class="chart-note">Gunakan alamat contoh untuk presentasi. Konfigurasi SMTP belum terhubung.</p></div></section><section class="panel"><div class="panel-header"><div><h2>Pratinjau email</h2><p>Contoh pesan dari aturan yang aktif</p></div><span class="badge sdk">PREVIEW</span></div>${emailPreview()}</section></div><section class="panel mt"><div class="panel-header"><div><h2>Log simulasi pengiriman</h2><p>Uji interaksi notifikasi tanpa mengirim pesan</p></div><span class="context-label">${saved.notificationLog.length} percobaan</span></div>${saved.notificationLog.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Waktu lokal</th><th>Penerima</th><th>Pemicu aktif</th><th>Hasil</th></tr></thead><tbody>${saved.notificationLog.map(l=>`<tr><td>${esc(l.time)}</td><td>${esc(l.recipient)}</td><td>${esc(l.rules)}</td><td>${badge('sdk','SIMULASI · TIDAK DIKIRIM')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Belum ada percobaan. Klik “Simulasikan email” untuk membuat log uji.</div>'}</section>`;}
function emailPreview(){const selected=Object.entries(saved.rules).filter(([,v])=>v).map(([k])=>k);const msg=selected.includes('alarm')?['[RMS Demo] R03 · Alarm controller','R03 / Side member · LH','Beban sumbu L tinggi — contoh event SIM-A01.']:selected.includes('offline')?['[RMS Demo] R08 · Koneksi terputus','R08 / Rear floor · RH','Sampel terakhir diterima 08:23:00. Kondisi fisik robot belum diketahui.']:selected.includes('pm')?['[RMS Demo] R03 · Pengingat PM','R03 / Side member · LH','Sisa interval PM contoh: 8 operating hours.']:selected.includes('digest')?['[RMS Demo] Ringkasan shift','Welding line 01','Utilization snapshot: 83,4%. Ada 2 alert yang perlu ditinjau.']:['Tidak ada aturan aktif','Welding line 01','Aktifkan minimal satu aturan untuk menyimulasikan notifikasi.'];return `<div class="mail-preview"><div class="mail-meta">To: <strong>${esc(saved.recipient)}</strong><br>Subject: <strong>${msg[0]}</strong></div><div class="mail-body"><div class="mail-brand">RMS<span style="color:#9abc87">.</span> <small style="font-size:9px;font-weight:400;letter-spacing:1px">ROBOT MONITORING</small></div><p>Halo Tim Maintenance,</p><p class="mt"><strong>${msg[1]}</strong><br>${msg[2]}</p><p class="mt">Tinjau detail dan riwayat melalui dashboard RMS.</p><div class="notice mt" style="font-size:9px">Pesan ilustratif untuk prototype · bukan email terkirim</div></div></div>`;}
function pipeline(){return `${heading('Data & koneksi','Lihat bagaimana data delapan controller menjadi informasi di dashboard.','SYSTEM / DATA PIPELINE',B('Lihat status fitur','nav-features','layers'))}<section class="panel mb"><div class="panel-header"><div><h2>Arsitektur sistem yang direncanakan</h2><p>8 robot · 1 welding line · pengumpulan data terpusat pada Mini PC</p></div><span class="badge sdk">RANCANGAN</span></div><div class="pipeline"><div class="pipeline-node">${I('robot')}<strong>8 robot Yaskawa</strong><p>Controller YRC1000<br>R01 hingga R08</p></div><div class="pipe-arrow">${I('arrow')}</div><div class="pipeline-node">${I('network')}<strong>Industrial switch</strong><p>16 port Ethernet<br>Jaringan robot</p></div><div class="pipe-arrow">${I('arrow')}</div><div class="pipeline-node focus">${I('server')}<strong>Mini PC · Ubuntu</strong><p>YMConnect C++<br>SLURBT · PostgreSQL</p></div><div class="pipe-arrow">${I('arrow')}</div><div class="pipeline-node">${I('monitor')}<strong>RMS dashboard</strong><p>Monitoring · Analitik<br>Maintenance · Notifikasi</p></div></div><div class="notice">${I('info')}Topologi ini adalah rancangan production. Website prototype ini menggunakan simulasi lokal dan tidak menjalankan collector.</div></section><div class="equal-col"><section class="panel"><div class="panel-header"><div><h2>SLURBT processing layer</h2><p>Pemrosesan data multi-robot</p></div>${I('layers')}</div>${[['01','Device management','Identitas robot dan parameter koneksi'],['02','Polling & scheduling','Pembacaan telemetry sesuai jadwal'],['03','Normalization & queue','Data seragam, timestamp, dan antrean'],['04','Error handling','Timeout, retry, dan penanda data stale'],['05','Storage & output','Histori PostgreSQL dan API dashboard']].map(([n,l,p])=>`<div class="event"><span class="event-icon green mono">${n}</span><div class="event-content"><strong>${l}</strong><p>${p}</p></div></div>`).join('')}</section><section class="panel"><div class="panel-header"><div><h2>Health snapshot</h2><p>Status komponen pada skenario simulasi</p></div><span class="badge sdk">DEMO</span></div>${[['Collector YMConnect','Simulasi aktif'],['SLURBT queue','0 backlog (contoh)'],['PostgreSQL','Data lokal prototype'],['API dashboard','Belum terhubung'],['Robot connections','7 / 8 online (demo)'],['Polling target','1.000 ms (contoh)'],['Last snapshot','12 Okt 2026 · 08:30']].map(([l,v])=>`<div class="kv-row"><span>${l}</span><strong>${v}</strong></div>`).join('')}<div class="chart-note">Performa polling aktual perlu diuji terhadap beban controller, jumlah fungsi, serta jaringan di lapangan.</div></section></div><section class="panel no-padding mt"><div style="padding:20px 20px 0" class="panel-header"><div><h2>Device registry</h2><p>Alamat berikut merupakan skema contoh untuk presentasi.</p></div>${I('network')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Robot</th><th>Station</th><th>Controller</th><th>IP contoh</th><th>Switch port</th><th>Status demo</th></tr></thead><tbody>${robots.map((r,i)=>`<tr><td><button class="action-link" data-robot="${r.id}">${r.id}</button></td><td>${r.station}</td><td>YRC1000</td><td class="mono">${r.ip}</td><td>P${String(i+1).padStart(2,'0')}</td><td>${badge(r.state==='offline'?'offline':'running',r.state==='offline'?'OFFLINE':'CONNECTED')}</td></tr>`).join('')}</tbody></table></div><div class="table-footer">P09: Mini PC · P10–P16: cadangan / rancangan lanjutan · IP dan port belum merupakan konfigurasi lapangan.</div></section>`;}
function hardware(){return `${heading('Hardware insights','Ruang investigasi untuk estimasi umur komponen berbasis data yang tervalidasi.','RESEARCH / HARDWARE LIFE')}<section class="hardware-hero"><div>${I('chip')}</div><div><span class="badge investigate">PERLU INVESTIGASI</span><h2>Bangun dasar datanya terlebih dahulu.</h2><p>Torque dan operating hours dapat menjadi masukan analisis, tetapi belum cukup untuk menampilkan sisa umur komponen secara andal. Prototype ini memperlihatkan kebutuhan data tanpa mengklaim nilai estimasi umur.</p></div></section><div class="three-col mt">${[['Reducer / gearbox','Tren beban, siklus, histori pelumasan'],['Servo motor','Jam servo, beban, temperatur jika tersedia'],['Kabel & komponen lain','Histori inspeksi, penggantian, dan failure']].map(([n,p])=>`<section class="panel"><div class="between"><h3>${n}</h3>${I('chip')}</div><div class="big-dash">— <small style="font-size:12px;letter-spacing:0">hours</small></div><p class="small muted">Sisa umur belum diestimasi</p><div class="chart-note">${p}</div><span class="badge investigate mt">DATA / MODEL BELUM TERVALIDASI</span></section>`).join('')}</div><div class="equal-col mt"><section class="panel"><div class="panel-header"><h2>Data yang perlu dipastikan</h2></div><ul class="check-list"><li>${I('file')}Referensi manufacturer dan kriteria umur setiap komponen.</li><li>${I('database')}Histori telemetry yang konsisten dan dapat ditelusuri.</li><li>${I('wrench')}Riwayat maintenance, kerusakan, dan penggantian aktual.</li><li>${I('activity')}Kondisi kerja, duty cycle, serta konteks beban proses.</li><li>${I('shield')}Validasi hasil estimasi terhadap kejadian nyata.</li></ul></section><section class="panel"><div class="panel-header"><h2>Nilai yang sudah bisa dibangun</h2></div><div class="event"><div class="event-icon green">${I('chart')}</div><div class="event-content"><strong>Tren pemakaian & beban</strong><p>Membandingkan telemetry antarperiode.</p></div></div><div class="event"><div class="event-icon green">${I('calendar')}</div><div class="event-content"><strong>PM berbasis counter jam</strong><p>Menjalankan interval yang ditentukan tim maintenance.</p></div></div><div class="event"><div class="event-icon green">${I('file')}</div><div class="event-content"><strong>Jejak pekerjaan & temuan</strong><p>Membangun dataset untuk investigasi berikutnya.</p></div></div>${B('Buka maintenance','nav-maintenance','arrow','text mt')}</section></div>`;}
const capabilities=[
 ['grid','Multi-robot overview','build','Bisa dibangun','Ringkasan dan detail delapan controller dalam satu dashboard.','overview'],
 ['monitor','Live controller status','sdk','SDK mendukung','Status mode, servo, cycle, dan koneksi controller.','detail','telemetry'],
 ['clock','Operating hours','sdk','SDK mendukung','Counter jam untuk pemakaian robot dan dasar PM.','detail','hours'],
 ['bell','Alarm management','partial','Sudah diuji sebagian','Alarm aktif, history, dan penandaan review pada dashboard.','alarms'],
 ['activity','Torque monitoring','tested','Sudah diuji','Pemantauan motor torque pada sumbu S, L, U, R, B, T.','detail','telemetry'],
 ['target','Position monitoring (PULSE)','tested','Sudah diuji','Pembacaan posisi sumbu dalam satuan PULSE.','detail','telemetry'],
 ['file','Job monitoring','sdk','SDK mendukung','Nama job dan informasi posisi eksekusi.','detail','job'],
 ['bolt','I/O monitoring','sdk','SDK mendukung','Pemantauan input/output dengan pemetaan sinyal.','detail','job'],
 ['wrench','Preventive maintenance','build','Bisa dibangun','Interval PM berdasarkan counter operating hours.','maintenance','tasks'],
 ['calendar','PM calendar & journal','build','Bisa dibangun','Penjadwalan, penanggung jawab, dan catatan pekerjaan.','maintenance','calendar'],
 ['mail','Email notification','build','Bisa dibangun','Aturan alert, pratinjau pesan, dan log notifikasi.','notifications'],
 ['chart','Downtime & utilization','build','Bisa dihitung','Durasi status dan pemanfaatan waktu terjadwal.','analytics'],
 ['chip','Hardware life estimation','investigate','Perlu investigasi','Kebutuhan data dan validasi estimasi umur komponen.','hardware']
];
function features(){return `${heading('Status pengembangan','Seluruh kemampuan dari gambar acuan, diterjemahkan menjadi alur interface.','PROJECT / DEVELOPMENT SCOPE',`${B('Reset data demo','reset-demo','refresh')}${B('Unduh offline','download-offline','download')}${B('Mulai presentasi','tour-start','play','primary')}`)}<div class="notice blue mb">${I('info')}Status di bawah mengikuti gambar acuan project. Kelengkapan tampilan prototype tidak berarti integrasi production sudah selesai.</div><div class="stats">${stat('Bisa dibangun / dihitung','5','Logika aplikasi & pemrosesan data','layers')}${stat('SDK mendukung','4','Pembacaan data controller','code')}${stat('Pernah diuji','3','2 diuji · 1 diuji sebagian','checkCircle')}${stat('Perlu investigasi','1','Estimasi umur hardware','chip','','warn')}</div><div class="capability-grid">${capabilities.map(([ico,title,status,label,desc,page,tab],i)=>`<article class="capability-card"><div class="between full-width">${I(ico)}<span class="mono muted">${String(i+1).padStart(2,'0')}</span></div><h3>${title}</h3>${badge(status==='build'?'running':status,label)}<p>${desc}</p><button class="btn text" data-capability="${i}">Buka prototype ${I('arrow')}</button></article>`).join('')}</div><div class="notice mt">${I('network')}Fondasi sistem yang direncanakan: YMConnect C++ + SLURBT + PostgreSQL.</div>`;}
const tourSteps=[
 {page:'overview',title:'01 · Satu line, delapan robot',text:'Mulai dari gambaran keseluruhan. Ada 5 robot running, 1 idle, 1 alarm, dan 1 offline. Semua angka pada prototype adalah data simulasi.'},
 {page:'detail',robot:'R01',tab:'telemetry',title:'02 · Dari overview ke telemetry',text:'Detail robot menampilkan status controller, grafik torque SLURBT, serta posisi dalam PULSE. Kedua pembacaan ini sudah diuji pada project sesuai acuan.'},
 {page:'detail',robot:'R01',tab:'job',title:'03 · Pahami pekerjaan robot',text:'Nama job, posisi eksekusi, dan kondisi I/O membantu menjelaskan aktivitas robot. Pemetaan sinyal di sini masih berupa contoh.'},
 {page:'detail',robot:'R03',tab:'hours',title:'04 · Jam operasi sebagai dasar PM',text:'Counter jam menjadi dasar perhitungan interval maintenance. Pada R03, contoh counter 4.992 jam mendekati interval PM di 5.000 jam.'},
 {page:'alarms',title:'05 · Tinjau alarm dan koneksi',text:'Klik Detail lalu Tandai ditinjau untuk demonstrasi review. Tindakan ini mencatat peninjauan di dashboard, tanpa melakukan reset alarm pada controller.'},
 {page:'maintenance',tab:'tasks',title:'06 · Jadwalkan dan catat pekerjaan',text:'Tunjukkan sisa interval PM, lalu coba Catat pekerjaan. Jurnal menyimpan PIC, tanggal, counter, hasil, dan catatan pada browser ini.'},
 {page:'maintenance',tab:'calendar',title:'07 · Kalender dan jurnal PM',text:'Jadwal memudahkan pembagian pekerjaan. Buka pekerjaan dari kalender atau tambahkan jadwal PM; hasilnya langsung terlihat di prototype.'},
 {page:'analytics',title:'08 · Ukur pemanfaatan waktu',text:'Utilization demo = 1.001 / 1.200 robot-menit, yaitu 83,4%. Unknown dipisahkan dari downtime. Coba pilihan periode untuk membandingkan dataset simulasi.'},
 {page:'notifications',title:'09 · Notifikasi ke maintenance',text:'Aktifkan aturan dan lihat pratinjau email. Tombol Simulasikan email menambah log uji lokal; tidak ada email yang dikirim.'},
 {page:'pipeline',title:'10 · Alur data end-to-end',text:'8 controller → industrial switch → Mini PC Ubuntu. YMConnect C++ membaca data, SLURBT memprosesnya, PostgreSQL menyimpan histori, lalu RMS menampilkan hasil.'},
 {page:'hardware',title:'11 · Batasan yang transparan',text:'Estimasi umur hardware masih perlu investigasi data dan validasi model. Karena itu tidak ada angka sisa umur yang diklaim oleh prototype.'},
 {page:'features',title:'12 · Ruang lingkup pengembangan',text:'Tutup dengan 13 fitur pada gambar acuan: 5 bisa dibangun/dihitung, 4 didukung SDK, 3 pernah diuji, dan 1 masih investigasi.'}
];
function navigate(p,opts={}){state.page=p;state.mobile=false;if(opts.robot)state.robot=opts.robot;if(opts.tab){if(p==='maintenance')state.pmTab=opts.tab;else state.tab=opts.tab;}if(p==='alarms'&&opts.reset){state.alarmTab='active';state.alarmSearch='';state.alarmRobot='all';state.alarmSeverity='all';}const hash=p==='detail'?`#robot/${state.robot}/${state.tab}`:`#${p}`;try{history.replaceState(null,'',hash);}catch{}closeModal(false);render(true);}
function stepTour(n){if(n<0||n>=tourSteps.length){state.tour=-1;renderTour();document.body.classList.remove('presentation');return;}state.tour=n;const s=tourSteps[n];if(s.page==='overview'){state.filter='all';state.layout='grid';}if(s.page==='analytics')state.period='shift';if(s.page==='maintenance'&&s.tab==='calendar'){state.month=9;state.year=2026;}navigate(s.page,{robot:s.robot,tab:s.tab,reset:true});}
function renderTour(){const root=$('#tour-root');if(state.tour<0){root.innerHTML='';return;}const s=tourSteps[state.tour];root.innerHTML=`<div class="presentation-banner"></div><aside class="tour" aria-label="Panduan presentasi"><div class="between"><span class="tour-label">PANDUAN PRESENTASI · ${state.tour+1} / ${tourSteps.length}</span><button class="icon-btn" data-action="tour-exit" aria-label="Tutup panduan">${I('close')}</button></div><h3>${s.title}</h3><p>${s.text}</p><div class="tour-bottom"><div class="tour-dots">${tourSteps.map((_,i)=>`<span class="${i===state.tour?'active':''}"></span>`).join('')}</div><div class="flex gap">${B('','tour-prev','back','small',`aria-label="Langkah sebelumnya" ${state.tour===0?'disabled':''}`)}${B(state.tour===tourSteps.length-1?'Selesai':'Lanjut','tour-next',state.tour===tourSteps.length-1?'check':'arrow','primary small')}</div></div><div class="between" style="margin-top:13px;font-size:8px;color:#89a67c"><span>← → navigasi · Esc tutup</span><button class="btn text small" style="color:#a8c699" data-action="fullscreen">${I('expand')} Layar penuh</button></div></aside>`;}
function toast(msg){clearTimeout(toastTimer);$('#toast-root').innerHTML=`<div class="toast">${I('checkCircle')}${esc(msg)}</div>`;toastTimer=setTimeout(()=>{$('#toast-root').innerHTML='';},4400);}
function modal(title,body,wide=false){modalOpener=document.activeElement;$('#overlay-root').innerHTML=`<div class="modal-backdrop" data-backdrop="true"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Tutup dialog">${I('close')}</button></div>${body}</section></div>`;document.body.style.overflow='hidden';const f=$('.modal input,.modal select,.modal textarea,.modal button');if(f)f.focus();}
function closeModal(restore=true){const root=$('#overlay-root');if(root)root.innerHTML='';document.body.style.overflow='';if(restore&&modalOpener?.isConnected)modalOpener.focus();}
function alarmDetail(id){const a=alarms().find(a=>a.id===id);if(!a)return;modal('Detail event',`<div class="between mb"><span class="mono muted">${a.code} · ${a.robot}</span>${severity(a)}</div><h3 style="font-size:17px">${a.title}</h3><p class="small muted mt" style="line-height:1.8">${a.detail}</p><div class="kv-row mt"><span>Sumber</span><strong>${a.kind}</strong></div><div class="kv-row"><span>Waktu tercatat</span><strong>12 Okt 2026 · ${a.time}</strong></div><div class="kv-row"><span>Kondisi event</span><strong>${a.active?'Masih aktif pada snapshot':'Sudah berakhir'}</strong></div><div class="kv-row"><span>Review dashboard</span><strong>${saved.acked.includes(id)?'Sudah ditinjau':'Belum ditinjau'}</strong></div><div class="notice blue mt">${I('info')}Review hanya mencatat peninjauan. Tidak ada perintah yang dikirim ke robot.</div><div class="modal-actions">${B('Lihat robot','modal-robot','robot','',`data-id="${a.robot}"`)}${a.active&&!saved.acked.includes(id)?B('Tandai ditinjau','ack-alarm','check','primary',`data-id="${id}"`):B('Tutup','close-modal')}</div>`);}
function taskDetail(id){const t=saved.tasks.find(t=>t.id===id);if(!t)return;const p=taskProgress(t);modal('Detail preventive maintenance',`<p class="modal-sub">${t.id} · ${t.robot} · ${p.r.station}</p><h3 style="font-size:17px">${esc(t.title)}</h3><div class="kv-row mt"><span>Jadwal</span><strong>${dateLabel(t.date)}</strong></div><div class="kv-row"><span>Penanggung jawab</span><strong>${esc(t.pic)}</strong></div><div class="kv-row"><span>Counter pada PM terakhir</span><strong>${fmt(t.base)} h</strong></div><div class="kv-row"><span>Counter saat ini (demo)</span><strong>${fmt(p.r.hours)} h</strong></div><div class="kv-row"><span>Interval contoh</span><strong>${fmt(t.interval)} h</strong></div><div class="kv-row"><span>Sisa interval</span><strong>${fmt(p.remaining)} h</strong></div><p class="small muted mt">${esc(t.note)}</p><div class="modal-actions">${B('Tutup','close-modal')}${t.status==='completed'?badge('running','TERCATAT'):B('Catat pekerjaan','complete-task','check','primary',`data-id="${esc(t.id)}"`)}</div>`);}
function newTask(){modal('Jadwalkan preventive maintenance',`<p class="modal-sub">Buat jadwal contoh. Perubahan tersimpan di browser ini.</p><form id="task-form"><div class="form-grid"><label class="field span">Nama pekerjaan<input required maxlength="80" class="input" name="title" placeholder="Contoh: Inspeksi berkala robot"></label><label class="field">Robot<select name="robot" class="input">${robots.map(r=>`<option value="${r.id}">${r.id} · ${r.name}</option>`).join('')}</select></label><label class="field">Tanggal rencana<input type="date" name="date" value="2026-10-14" required class="input"></label><label class="field">Interval PM (jam)<input name="interval" type="number" min="1" max="100000" value="1000" required class="input"></label><label class="field">Counter pada PM terakhir (jam)<input name="base" type="number" min="0" max="${robots[0].hours}" value="4000" required class="input"></label><label class="field span">Penanggung jawab<input name="pic" maxlength="60" required class="input" placeholder="Tim Maintenance A"></label><label class="field span">Catatan<textarea name="note" maxlength="600" class="input" placeholder="Lingkup pekerjaan atau catatan jadwal..."></textarea></label></div><p class="chart-note">Counter saat ini mengikuti data robot demo. Interval yang dimasukkan hanya untuk simulasi.</p><div class="modal-actions">${B('Batal','close-modal','','','type="button"')}<button class="btn primary" type="submit">${I('calendar')}Simpan jadwal</button></div></form>`);}
function completeTask(id){const t=saved.tasks.find(t=>t.id===id);if(!t)return;const r=robots.find(r=>r.id===t.robot);modal('Catat pekerjaan maintenance',`<p class="modal-sub">${t.robot} · ${esc(t.title)}</p><form id="complete-form" data-id="${esc(id)}"><div class="form-grid"><label class="field">Tanggal pekerjaan<input type="date" name="date" value="2026-10-12" required class="input"></label><label class="field">Counter saat pekerjaan (jam)<input type="number" min="${t.base}" max="${r.hours}" name="hours" value="${r.hours}" required class="input"></label><label class="field">Penanggung jawab<input name="pic" class="input" value="${esc(t.pic)}" required maxlength="60"></label><label class="field">Hasil<select name="result" class="input"><option>Selesai</option><option>Perlu tindak lanjut</option></select></label><label class="field span">Catatan hasil<textarea name="notes" class="input" required minlength="5" maxlength="1200" placeholder="Catat hasil inspeksi dan temuan...">Contoh pencatatan pekerjaan selesai untuk demonstrasi RMS.</textarea></label></div><div class="notice mt">${I('file')}Penyimpanan membuat jurnal lokal dan menutup jadwal demo ini.</div><div class="modal-actions">${B('Batal','close-modal','','','type="button"')}<button class="btn primary" type="submit">${I('check')}Simpan jurnal</button></div></form>`);}
function openSearch(){modal('Cari di RMS',`<input id="global-search" class="input full-width" type="search" placeholder="Cari R03, torque, kalender, alarm..." aria-label="Cari di RMS" autocomplete="off"><div class="search-results" id="global-results">${searchResults('')}</div>`);}
function searchResults(q){const query=q.trim().toLowerCase();const list=[...robots.map(r=>({type:'robot',key:r.id,title:`${r.id} · ${r.name}`,desc:r.station,icon:'robot'})),...capabilities.map((c,i)=>({type:'feature',key:i,title:c[1],desc:c[4],icon:c[0]}))].filter(x=>`${x.title} ${x.desc}`.toLowerCase().includes(query)).slice(0,8);return list.map(x=>`<button class="search-result" ${x.type==='robot'?`data-robot="${x.key}"`:`data-capability="${x.key}"`}>${I(x.icon)}<div><strong>${x.title}</strong><p>${x.desc}</p></div><span style="margin-left:auto">${I('arrow')}</span></button>`).join('')||'<div class="empty">Tidak ada hasil. Coba nama robot atau fitur.</div>';}
function csvDownload(name,rows){const cell=v=>{let s=String(v??'');if(/^[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const csv='\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('CSV data simulasi berhasil disiapkan.');}
function exportAlarms(){csvDownload('RMS_Alarm_Simulasi.csv',[['Data','Waktu','Robot','Kode ilustratif','Sumber','Event','Severity','Status event','Review'],...filteredAlarms().map(a=>['SIMULASI',a.time,a.robot,a.code,a.kind,a.title,a.severity,a.active?'Aktif':'Berakhir',saved.acked.includes(a.id)?'Ditinjau':'Belum ditinjau'])]);}
function exportJournal(){csvDownload('RMS_Jurnal_PM_Simulasi.csv',[['Data','Tanggal','Robot','Pekerjaan','Counter jam','PIC','Hasil','Catatan'],...saved.journal.map(j=>['SIMULASI',j.date,j.robot,j.title,j.hours,j.pic,j.result,j.notes])]);}
function exportAnalytics(){const d=analyticsData();csvDownload('RMS_Utilization_Simulasi.csv',[['Data','Periode','Robot','Running menit','Terjadwal menit','Utilization persen'],...robots.map((r,i)=>['SIMULASI',d.label,r.id,d.perRobot[i],d.minutes,(d.perRobot[i]/d.minutes*100).toFixed(2)]),[],['Komposisi akumulasi','Running','Idle','Stop','Unknown','Total'],['Robot-menit',d.run,d.idle,d.stop,d.unknown,d.total]]);}
function featureNavigate(i){const c=capabilities[Number(i)];if(!c)return;const [,title,,,desc,page,tab]=c;navigate(page,{robot:page==='detail'?'R01':undefined,tab});}
function handleAction(action,el){
 if(action.startsWith('nav-')){navigate(action.slice(4));return;}
 switch(action){
 case 'menu':state.mobile=!state.mobile;$('.sidebar').classList.toggle('open',state.mobile);break;
 case 'live':state.live=!state.live;render();toast(state.live?'Animasi data simulasi dilanjutkan.':'Animasi dijeda untuk presentasi.');break;
 case 'date':modal('Snapshot presentasi',`<p class="small muted" style="line-height:1.9">Dataset utama menggambarkan <strong>12 Oktober 2026, 08:30</strong>, dengan periode analisis shift berjalan <strong>06:00–08:30</strong>.<br><br>Seluruh angka, nama station, job, alamat IP, alarm, dan aktivitas merupakan contoh. Animasi torque dapat dijeda tanpa mengubah snapshot analitik.</p><div class="modal-actions">${B('Mengerti','close-modal','','primary')}</div>`);break;
 case 'search':openSearch();break;
 case 'tour-start':stepTour(0);break;
 case 'tour-next':stepTour(state.tour+1);break;
 case 'tour-prev':stepTour(state.tour-1);break;
 case 'tour-exit':stepTour(-1);break;
 case 'fullscreen':if(document.fullscreenElement){document.exitFullscreen?.().catch(()=>{});}else if(document.documentElement.requestFullscreen){document.documentElement.requestFullscreen().catch(()=>toast('Gunakan F11 pada browser untuk layar penuh.'));}else{toast('Gunakan tombol layar penuh pada browser.');}break;
 case 'close-modal':closeModal();break;
 case 'alarm-detail':alarmDetail(el.dataset.id);break;
 case 'modal-robot':navigate('detail',{robot:el.dataset.id,tab:'telemetry'});break;
 case 'ack-alarm':if(!saved.acked.includes(el.dataset.id)){saved.acked.push(el.dataset.id);persist();}closeModal();render();toast('Event ditandai ditinjau. Kondisi alarm tetap aktif.');break;
 case 'reset-alarm-filter':state.alarmSearch='';state.alarmRobot='all';state.alarmSeverity='all';render();break;
 case 'task-detail':taskDetail(el.dataset.id);break;
 case 'new-task':newTask();break;
 case 'complete-task':completeTask(el.dataset.id);break;
 case 'month-prev':case 'month-next':{const d=new Date(state.year,state.month+(action==='month-next'?1:-1),1);state.month=d.getMonth();state.year=d.getFullYear();render();break;}
 case 'month-now':state.month=9;state.year=2026;render();break;
 case 'save-recipient':{const input=$('#recipient');if(!input.value.trim()){input.setCustomValidity('Masukkan alamat email demo.');input.reportValidity();break;}input.setCustomValidity('');if(!input.checkValidity()){input.reportValidity();break;}saved.recipient=input.value.trim();persist();render();toast('Penerima demo tersimpan. Tidak ada email terkirim.');break;}
 case 'test-email':{const active=Object.entries(saved.rules).filter(([,v])=>v).map(([k])=>({alarm:'Alarm',offline:'Offline',pm:'PM',digest:'Ringkasan'}[k]));if(!active.length){toast('Aktifkan minimal satu aturan notifikasi.');break;}saved.notificationLog.unshift({time:new Date().toLocaleString('id-ID',{hour12:false}),recipient:saved.recipient,rules:active.join(', ')});saved.notificationLog=saved.notificationLog.slice(0,20);persist();render();toast('Simulasi dicatat. Tidak ada email yang dikirim.');break;}
 case 'download-offline':{if(location.protocol==='file:'){toast('Versi offline sudah terbuka. Simpan file HTML ini untuk presentasi.');break;}const a=document.createElement('a');a.href='rms-prototype-offline.html';a.download='RMS_Prototype_Offline.html';a.click();toast('Prototype offline siap diunduh sebagai satu file HTML.');break;}
 case 'export-alarms':exportAlarms();break;
 case 'export-journal':exportJournal();break;
 case 'export-analytics':exportAnalytics();break;
 case 'reset-demo':modal('Reset data demo?',`<p class="small muted" style="line-height:1.9">Jadwal tambahan, jurnal demo, review alarm, aturan notifikasi, dan log uji pada browser ini akan kembali ke data awal.</p><div class="modal-actions">${B('Batal','close-modal')}${B('Reset demo','confirm-reset','refresh','danger')}</div>`);break;
 case 'confirm-reset':saved=defaults();persist();state.filter='all';state.layout='grid';state.alarmSearch='';state.alarmRobot='all';state.alarmSeverity='all';state.month=9;state.year=2026;closeModal();render();toast('Data demo dikembalikan ke kondisi awal.');break;
 }
}
document.addEventListener('click',e=>{
 const el=e.target.closest('button,[data-backdrop]');if(!el)return;
 if(el.dataset.backdrop&&e.target===el){closeModal();return;}
 if(el.dataset.action){handleAction(el.dataset.action,el);return;}
 if(el.dataset.page){navigate(el.dataset.page);return;}
 if(el.dataset.robot){navigate('detail',{robot:el.dataset.robot,tab:'telemetry'});return;}
 if(el.dataset.capability!==undefined){featureNavigate(el.dataset.capability);return;}
 if(el.dataset.filter){state.filter=el.dataset.filter;render();return;}
 if(el.dataset.layout){state.layout=el.dataset.layout;render();return;}
 if(el.dataset.tab){state.tab=el.dataset.tab;navigate('detail',{robot:state.robot,tab:state.tab});return;}
 if(el.dataset.alarmTab){state.alarmTab=el.dataset.alarmTab;render();return;}
 if(el.dataset.pmTab){state.pmTab=el.dataset.pmTab;render();return;}
 if(el.dataset.rule){saved.rules[el.dataset.rule]=!saved.rules[el.dataset.rule];persist();render();return;}
});
document.addEventListener('input',e=>{
 if(e.target.id==='global-search')$('#global-results').innerHTML=searchResults(e.target.value);
 if(e.target.id==='alarm-search'){state.alarmSearch=e.target.value;const list=filteredAlarms();$('#alarm-results').innerHTML=alarmTable(list);$('#alarm-result-count').textContent=`Menampilkan ${list.length} event · seluruh data adalah simulasi`;}
 if(e.target.id==='recipient')e.target.setCustomValidity('');
});
document.addEventListener('change',e=>{
 const id=e.target.id;
 if(id==='robot-select'){navigate('detail',{robot:e.target.value,tab:state.tab});return;}
 if(id==='alarm-robot'){state.alarmRobot=e.target.value;render();}
 if(id==='alarm-severity'){state.alarmSeverity=e.target.value;render();}
 if(id==='analytics-period'){state.period=e.target.value;render();}
 if(e.target.name==='robot'&&e.target.form?.id==='task-form'){const r=robots.find(r=>r.id===e.target.value),input=e.target.form.elements.base;input.max=r.hours;if(Number(input.value)>r.hours)input.value=Math.max(0,r.hours-500);}
});
document.addEventListener('submit',e=>{
 if(e.target.id==='task-form'){
  e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));const r=robots.find(r=>r.id===d.robot);
  if(!d.title.trim()||!d.pic.trim()){toast('Isi nama pekerjaan dan penanggung jawab.');return;}
  if(!r||Number(d.base)>r.hours||Number(d.base)<0||Number(d.interval)<=0){toast('Periksa interval dan counter PM terakhir.');return;}
  saved.tasks.push({id:'PM'+Date.now().toString(36),robot:d.robot,title:d.title.trim(),date:d.date,pic:d.pic.trim(),base:Number(d.base),interval:Number(d.interval),note:d.note.trim(),status:'scheduled'});persist();closeModal();state.pmTab='calendar';const dt=new Date(d.date+'T12:00:00');state.month=dt.getMonth();state.year=dt.getFullYear();render();toast('Jadwal PM tersimpan di kalender demo.');
 }
 if(e.target.id==='complete-form'){
  e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f)),t=saved.tasks.find(t=>t.id===f.dataset.id);if(!t||t.status==='completed')return;
  if(!d.pic.trim()||d.notes.trim().length<5){toast('Isi penanggung jawab dan catatan hasil yang cukup.');return;}
  t.status='completed';saved.journal.unshift({id:'J'+Date.now().toString(36),robot:t.robot,title:t.title,date:d.date,pic:d.pic.trim(),hours:Number(d.hours),notes:d.notes.trim(),result:d.result});persist();closeModal();state.pmTab='journal';render();toast('Pekerjaan dicatat pada jurnal maintenance demo.');
 }
});
document.addEventListener('keydown',e=>{
 const dialog=$('.modal'),editing=/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName);
 if(e.key==='Escape'){if(dialog)closeModal();else if(state.tour>=0)stepTour(-1);else if(state.mobile){state.mobile=false;$('.sidebar').classList.remove('open');}return;}
 if(dialog&&e.key==='Tab'){const focusable=$$('button:not([disabled]),input,select,textarea,a[href]',dialog);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}return;}
 if(editing||dialog)return;
 if(e.key==='/'){e.preventDefault();openSearch();}
 if(state.tour>=0&&e.key==='ArrowRight'){e.preventDefault();stepTour(state.tour+1);}
 if(state.tour>0&&e.key==='ArrowLeft'){e.preventDefault();stepTour(state.tour-1);}
});
function routeFromHash(){const h=location.hash.slice(1).split('/');if(h[0]==='robot'&&robots.some(r=>r.id===h[1])){state.page='detail';state.robot=h[1];state.tab=['telemetry','job','hours','events'].includes(h[2])?h[2]:'telemetry';}else if(navs.some(n=>n[0]===h[0]))state.page=h[0];else state.page='overview';render();}
window.addEventListener('hashchange',routeFromHash);
routeFromHash();
setInterval(()=>{if(!state.live)return;state.tick++;const clock=$('#live-time');if(clock)clock.textContent=`08:30:${String(state.tick%60).padStart(2,'0')}`;if(state.page==='detail'&&state.tab==='telemetry'){const r=robots.find(r=>r.id===state.robot),vals=torqueValues(r);$$('[data-torque]').forEach(el=>{const v=vals[Number(el.dataset.torque)];el.textContent=v===null?'—':fmt(v,1);});const plot=$('#torque-plot');if(plot)plot.innerHTML=chart(r);}},2200);
